<style>.report-eyebrow{color:#0b5ea8;font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em}.report-stat{height:100%;padding:15px 17px;background:#fff;border:1px solid #dbe5ef;border-top:4px solid #64748b}.report-stat span,.report-stat small{display:block;color:#64748b;font-size:.76rem}.report-stat strong{display:block;font-size:1.55rem}.report-stat.total{border-top-color:#0b5ea8}.report-stat.good{border-top-color:#159957}.report-stat.attention{border-top-color:#dc2626}.report-stat.neutral{border-top-color:#94a3b8}.report-stat.accent{border-top-color:#f6b322}.report-stat.info{border-top-color:#38bdf8}.report-card,.report-filter{border:1px solid #dbe5ef}.report-card .card-header,.report-filter .card-header{background:#f8fafc}.report-filter .form-label{font-size:.76rem;font-weight:700;color:#475569;margin-bottom:3px}</style>
